   cloze('أكمل الأبنية الأربعة', 'الأوّل ___ مطلق مبيّن للنوع، والثاني ___ تامّ منفيّ، والثالث مبنيّ ___، والرابع جملة ___.', ['مفعول', 'استثناء', 'للمجهول', 'اعتراضية'], ['فاعل', 'شرط', 'للمعلوم', 'فعلية']),
   cloze('أكمل قاعدة لولا', 'ما بعد لولا ___ مرفوع وخبره ___ وجوبًا، ولولا حرف ___ لوجود.', ['مبتدأ', 'محذوف', 'امتناع'], ['مفعول', 'مذكور', 'شرط']),
