   tf('قالت هند إنّ في المسودّة الأولى أخطاء نحوية.', 'هند: التقرير صحيح، وكلّ جملة فيه سليمة، لكنّه يمشي على رجل واحدة.', 'false', 'لا خطأ نحويًّا فيها.'),
   tf('قال كين إنّ يوسف هو الذي نبّهه إلى رفع «المنحة».', 'كين: فقال لي يوسف إنّ «المنحة» مرفوعة، وأنا ظننتها منصوبة.', 'true', 'يوسف محقّ.'),
   tf('سلّمت ماريا المسودّة الثانية في الموعد.', 'هند: المسودّة الثانية بعد أسبوع، وفي كلّ صفحة ثلاثة أبنية على الأقلّ.', 'ng', 'لم يُذكر تسليمها.'),
   tap('المس المفعول المطلق', ['تعلّم', 'طلّابُ', 'القصّة', 'الكلماتِ', 'تعلّمًا', 'أسرعَ'], 'تعلّمًا'),
